class Mailer:
    def send(self, to: str, subject: str, body: str, retries: int = 5) -> bool:
        for _ in range(retries):
            if self._smtp.send(to, subject, body):
                return True
        return False

    def format_name(self, first: str, last: str) -> str:
        return f"{last}, {first}"
